"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[97972],{3331:(e,s,i)=>{i.d(s,{R:()=>a,x:()=>o});var n=i(36672);const t={},r=n.createContext(t);function a(e){const s=n.useContext(r);return n.useMemo((function(){return"function"==typeof e?e(s):{...s,...e}}),[s,e])}function o(e){let s;return s=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:a(e.components),n.createElement(r.Provider,{value:s},e.children)}},66377:(e,s,i)=>{i.r(s),i.d(s,{assets:()=>l,contentTitle:()=>o,default:()=>c,frontMatter:()=>a,metadata:()=>n,toc:()=>u});const n=JSON.parse('{"id":"2023/04/06","title":"2023-04-06","description":"En souvenir de Bob Lee","source":"@site/i18n/fr/docusaurus-plugin-content-docs/current/2023/04/06.md","sourceDirName":"2023/04","slug":"/2023/04/06","permalink":"/fr/2023/04/06","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/fr/docusaurus-plugin-content-docs//current/2023/04/06.md","tags":[],"version":"current","frontMatter":{"localized_date":"6 avril 2023","top_news":"En souvenir de Bob Lee"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-07","permalink":"/fr/2023/04/07"},"next":{"title":"2023-04-05","permalink":"/fr/2023/04/05"}}');var t=i(23420),r=i(3331);const a={localized_date:"6 avril 2023",top_news:"En souvenir de Bob Lee"},o="2023-04-06",l={},u=[{value:"En souvenir de Bob Lee",id:"en-souvenir-de-bob-lee",level:2},{value:"Bob Lee, ancien directeur technique de Square, est d\xe9c\xe9d\xe9 apr\xe8s avoir \xe9t\xe9 poignard\xe9 \xe0 San Francisco.",id:"bob-lee-ancien-directeur-technique-de-square-est-d\xe9c\xe9d\xe9-apr\xe8s-avoir-\xe9t\xe9-poignard\xe9-\xe0-san-francisco",level:2},{value:"Tell Discussion Service : iOS permet aux op\xe9rateurs d&#39;ajouter des r\xe9seaux WiFi qu&#39;il est impossible d&#39;emp\xeacher de rejoindre",id:"tell-discussion-service--ios-permet-aux-op\xe9rateurs-dajouter-des-r\xe9seaux-wifi-quil-est-impossible-demp\xeacher-de-rejoindre",level:2},{value:"Les fondements de l&#39;apprentissage profond pour une diffusion stable",id:"les-fondements-de-lapprentissage-profond-pour-une-diffusion-stable",level:2},{value:"CAN Injection : Vol de voiture sans cl\xe9",id:"can-injection--vol-de-voiture-sans-cl\xe9",level:2},{value:"Les ing\xe9nieurs de Firefox d\xe9couvrent un bogue de Windows Defender qui entra\xeene une utilisation \xe9lev\xe9e de l&#39;unit\xe9 centrale.",id:"les-ing\xe9nieurs-de-firefox-d\xe9couvrent-un-bogue-de-windows-defender-qui-entra\xeene-une-utilisation-\xe9lev\xe9e-de-lunit\xe9-centrale",level:2},{value:"Segment Anything Model (SAM) peut &quot;d\xe9couper&quot; n&#39;importe quel objet dans une image",id:"segment-anything-model-sam-peut-d\xe9couper-nimporte-quel-objet-dans-une-image",level:2},{value:"Le livre blanc de Bitcoin est cach\xe9 dans chaque copie de macOS",id:"le-livre-blanc-de-bitcoin-est-cach\xe9-dans-chaque-copie-de-macos",level:2},{value:"L&#39;ancien directeur technique de Square, Bob Lee, poignard\xe9 \xe0 mort dans le centre de San Francisco",id:"lancien-directeur-technique-de-square-bob-lee-poignard\xe9-\xe0-mort-dans-le-centre-de-san-francisco",level:2},{value:"Les arguments en faveur de l&#39;interdiction des m\xe9dias sociaux aux enfants",id:"les-arguments-en-faveur-de-linterdiction-des-m\xe9dias-sociaux-aux-enfants",level:2},{value:"Dang aura bient\xf4t 65 535 points de karma.",id:"dang-aura-bient\xf4t-65-535-points-de-karma",level:2},{value:"R\xe9seaux neuronaux : De z\xe9ro \xe0 h\xe9ros",id:"r\xe9seaux-neuronaux--de-z\xe9ro-\xe0-h\xe9ros",level:2},{value:"Une astuce pour atteindre le flux : Laissez votre travail bris\xe9",id:"une-astuce-pour-atteindre-le-flux--laissez-votre-travail-bris\xe9",level:2},{value:"La RAM est-elle effac\xe9e avant d&#39;\xeatre utilis\xe9e dans un autre conteneur LXC ?",id:"la-ram-est-elle-effac\xe9e-avant-d\xeatre-utilis\xe9e-dans-un-autre-conteneur-lxc-",level:2},{value:"Perspective : BI Open Source aliment\xe9e par WebAssembly",id:"perspective--bi-open-source-aliment\xe9e-par-webassembly",level:2},{value:"Grid World",id:"grid-world",level:2},{value:"OpenAI Tokenizer",id:"openai-tokenizer",level:2},{value:"Tabloid - Le langage de programmation des titres racoleurs",id:"tabloid---le-langage-de-programmation-des-titres-racoleurs",level:2},{value:"GPT4 simulant un serveur FTP \xe0 ftp.disney.com",id:"gpt4-simulant-un-serveur-ftp-\xe0-ftpdisneycom",level:2},{value:"Utilisation de mmap pour acc\xe9l\xe9rer le chargement de LLaMA",id:"utilisation-de-mmap-pour-acc\xe9l\xe9rer-le-chargement-de-llama",level:2}];function d(e){const s={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,r.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(s.header,{children:(0,t.jsx)(s.h1,{id:"2023-04-06",children:"2023-04-06"})}),"\n",(0,t.jsx)(s.h2,{id:"en-souvenir-de-bob-lee",children:"En souvenir de Bob Lee"}),"\n",(0,t.jsx)(s.p,{children:"La communaut\xe9 technologique pleure la perte de Bob Lee, une figure bien connue de l'industrie. M. Lee \xe9tait un d\xe9fenseur de Java, ayant travaill\xe9 chez Google et Square, et \xe9tait connu pour son travail sur le cadre d'injection de d\xe9pendance Guice. Il \xe9tait \xe9galement cofondateur de l'Android Alliance, une initiative visant \xe0 promouvoir l'innovation dans l'\xe9cosyst\xe8me Android. Les contributions de Lee au monde de la technologie \xe9taient largement reconnues, et il manquera beaucoup \xe0 ses coll\xe8gues et \xe0 ses pairs. Nombreux sont ceux qui ont partag\xe9 leurs condol\xe9ances sur les m\xe9dias sociaux, se souvenant de Lee comme d'un mentor et d'un ami qui prenait toujours le temps de s'occuper des autres. Repose en paix, Bob Lee."}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35457341",children:"Discussion Service"}),".\nBob Lee, coauteur de Guice et des biblioth\xe8ques Java, r\xe9put\xe9 pour ses comp\xe9tences techniques, sa gentillesse et son humilit\xe9, est d\xe9c\xe9d\xe9. Son d\xe9c\xe8s a endeuill\xe9 la communaut\xe9 technologique et a incit\xe9 de nombreuses personnes \xe0 partager leurs souvenirs et anecdotes \xe0 son sujet. L'h\xe9ritage d'innovation et de passion de Lee en a inspir\xe9 plus d'un, et sa contribution \xe0 l'industrie nous manquera. Bien que certains commentaires se soient \xe9loign\xe9s de la r\xe9alit\xe9, la plupart ont partag\xe9 des pens\xe9es et des exp\xe9riences positives \xe0 propos de Bob."]}),"\n",(0,t.jsx)(s.h2,{id:"bob-lee-ancien-directeur-technique-de-square-est-d\xe9c\xe9d\xe9-apr\xe8s-avoir-\xe9t\xe9-poignard\xe9-\xe0-san-francisco",children:"Bob Lee, ancien directeur technique de Square, est d\xe9c\xe9d\xe9 apr\xe8s avoir \xe9t\xe9 poignard\xe9 \xe0 San Francisco."}),"\n",(0,t.jsxs)(s.p,{children:["(",(0,t.jsx)(s.a,{href:"https://www.sfgate.com/bayarea/article/mill-valley-man-killed-sf-stabbing-17878809.php",children:"https://www.sfgate.com/bayarea/article/mill-valley-man-killed-sf-stabbing-17878809.php"}),").\nBob Lee, le cr\xe9ateur de Cash App en tant que directeur de la technologie chez Square, a \xe9t\xe9 identifi\xe9 comme l'homme qui a \xe9t\xe9 tu\xe9 \xe0 San Francisco \xe0 la suite d'un incident de poignardage ; l'\xe9v\xe9nement a choqu\xe9 le monde de la technologie, les gens r\xe9agissant \xe0 la nouvelle soudaine. La police n'a proc\xe9d\xe9 \xe0 aucune arrestation et n'a communiqu\xe9 aucune information concernant d'\xe9ventuels suspects. Lee, \xe2g\xe9 de 43 ans, \xe9tait le fondateur de Cash App et travaillait comme Chief Product Officer chez MobileCoin au moment de sa mort."]}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35448899",children:"Discussion Service"}),".\nL'ancien directeur technique de Square, Bob Lee, tu\xe9 \xe0 San Francisco, suscite un d\xe9bat sur la criminalit\xe9 et la gouvernance. Les commentaires portent sur la disparit\xe9 des richesses, les sans-abri, l'embourgeoisement et les solutions potentielles. Le d\xe9bat soul\xe8ve des questions sur les syst\xe8mes politiques et les statistiques criminelles peu fiables dans les villes am\xe9ricaines. Les utilisateurs discutent des causes potentielles de la criminalit\xe9, notamment les migrations massives, l'in\xe9galit\xe9 des richesses, l'impact des syst\xe8mes judiciaires et le manque de r\xe9activit\xe9 de la police. Il n'est pas utile de comparer la criminalit\xe9 entre diff\xe9rents pays ou cultures. La question de la criminalit\xe9 est complexe et ne r\xe9sulte pas d'un seul facteur."]}),"\n",(0,t.jsx)(s.h2,{id:"tell-discussion-service--ios-permet-aux-op\xe9rateurs-dajouter-des-r\xe9seaux-wifi-quil-est-impossible-demp\xeacher-de-rejoindre",children:"Tell Discussion Service : iOS permet aux op\xe9rateurs d'ajouter des r\xe9seaux WiFi qu'il est impossible d'emp\xeacher de rejoindre"}),"\n",(0,t.jsx)(s.p,{children:"Le syst\xe8me d'exploitation iOS permet aux op\xe9rateurs d'ajouter des r\xe9seaux WiFi auxquels les utilisateurs ne peuvent pas s'opposer. Cette fonctionnalit\xe9 inqui\xe8te les utilisateurs d'iPhone dont les plans de donn\xe9es sont limit\xe9s ou qui sont pr\xe9occup\xe9s par la protection de leur vie priv\xe9e. Cette fonction a pour but d'aider les op\xe9rateurs \xe0 lancer des points d'acc\xe8s WiFi, mais elle leur permet \xe9galement d'ajouter des r\xe9seaux WiFi publics auxquels les utilisateurs se connectent \xe0 leur insu, ce qui peut entra\xeener la collecte de donn\xe9es sensibles. Les utilisateurs disposent d'un nombre limit\xe9 d'options pour d\xe9sactiver la fonction, notamment la d\xe9sactivation compl\xe8te du WiFi ou le choix d'\"oublier ce r\xe9seau\" chaque fois qu'ils le rencontrent. Certains utilisateurs demandent \xe0 Apple de mieux contr\xf4ler cette fonctionnalit\xe9, tandis que d'autres sugg\xe8rent d'utiliser un VPN pour prot\xe9ger leurs donn\xe9es."}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35447486",children:"Discussion Service"}),".\niOS 16.4 permet aux op\xe9rateurs d'ajouter des r\xe9seaux g\xe9r\xe9s aux appareils, de r\xe9duire les co\xfbts de t\xe9l\xe9phonie mobile et d'emp\xeacher la d\xe9sactivation de la jonction automatique, sans qu'il soit possible de supprimer ces r\xe9seaux autrement qu'en r\xe9initialisant les param\xe8tres r\xe9seau. Les utilisateurs signalent que T-Mobile vole des donn\xe9es et que les r\xe9seaux Wingman en vol ne s'\xe9teignent pas, et se disent choqu\xe9s par le fait que les op\xe9rateurs dictent les connexions WiFi sans que l'utilisateur n'ait de recours. Un d\xe9bat s'ensuit sur la mani\xe8re d'obtenir un contr\xf4le complet de l'appareil, certains utilisateurs recommandant GrapheneOS pour les mises \xe0 jour de s\xe9curit\xe9. Les hotspots WiFi des op\xe9rateurs sont critiqu\xe9s parce qu'ils perturbent les connexions aux appareils locaux, alors que certains trouvent cette fonction utile dans les zones tr\xe8s fr\xe9quent\xe9es."]}),"\n",(0,t.jsx)(s.h2,{id:"les-fondements-de-lapprentissage-profond-pour-une-diffusion-stable",children:"Les fondements de l'apprentissage profond pour une diffusion stable"}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"https://course.fast.ai/Lessons/part2.html",children:"Original"}),".\n\"Practical Deep Learning for Coders - Part 2\" est un cours de plus de 30 heures de contenu vid\xe9o qui comprend la couverture de l'algorithme Stable Diffusion \xe0 partir de z\xe9ro, en \xe9troite collaboration avec des experts de Stable.ai et Hugging Face. Le cours fournit une couverture rigoureuse des derni\xe8res techniques et va m\xeame au-del\xe0 de ce que Stable Diffusion inclut, ce qui en fait un excellent objectif d'apprentissage pour de nombreuses raisons, cependant, pour tirer le meilleur parti de ce cours, vous devez \xeatre un praticien de l'apprentissage profond raisonnablement confiant. Tout au long du cours, nous explorerons les m\xe9thodes de diffusion, nous impl\xe9menterons nos propres mod\xe8les \xe0 partir de z\xe9ro, nous ma\xeetriserons les concepts de Python et nous utiliserons PyTorch pour impl\xe9menter nos mod\xe8les. Nous couvrirons les fondements de la diffusion, les optimiseurs d'apprentissage profond, les concepts Python, les fondements de base, la g\xe9n\xe9ration de nombres pseudo-al\xe9atoires, les architectures de r\xe9seaux neuronaux, les architectures g\xe9n\xe9ratives, les transformateurs et l'entra\xeenement de pr\xe9cision mixte."]}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35449831",children:"Discussion Service"}),".\nLe cours \"Deep Learning Foundations to Stable Diffusion\" explore la mod\xe9lisation g\xe9n\xe9rative moderne, tandis que certains recommandent de se concentrer sur le marketing. Le cours d'apprentissage profond de Fast.ai cr\xe9e un cadre de programmation \xe0 partir de z\xe9ro et est recommand\xe9 \xe0 tous ceux qui s'y int\xe9ressent. Le d\xe9bat porte sur les dangers potentiels de l'IA avanc\xe9e et sur l'importance de la r\xe9glementation et des consid\xe9rations \xe9thiques. Les commentateurs sugg\xe8rent d'interdire la production d'IA, mais ce n'est pas une solution \xe0 long terme \xe0 moins que tous les pays ne le fassent. Le cours de FastAI ne contient pas de d\xe9clarations politiquement ou religieusement biais\xe9es, et son contenu est consid\xe9r\xe9 comme de premier ordre. Le cours est accessible \xe0 toute personne ayant des connaissances de base en math\xe9matiques du secondaire et couvre des concepts avanc\xe9s."]}),"\n",(0,t.jsx)(s.h2,{id:"can-injection--vol-de-voiture-sans-cl\xe9",children:"CAN Injection : Vol de voiture sans cl\xe9"}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"https://kentindell.github.io/2023/04/03/can-injection/",children:"Original"}),".\nLes voleurs de voitures utilisent une nouvelle technique appel\xe9e injection CAN pour contourner les syst\xe8mes de cl\xe9s intelligentes dans les voitures modernes en exploitant les vuln\xe9rabilit\xe9s du protocole de communication du bus CAN. Les syst\xe8mes de s\xe9curit\xe9 automobile sophistiqu\xe9s, y compris les dispositifs d'immobilisation du moteur, sont devenus vuln\xe9rables. Les voleurs utilisent un dispositif appel\xe9 CAN Injector pour voler les voitures sans la cl\xe9 en injectant de faux messages dans le syst\xe8me de communication interne de la voiture. Le dispositif co\xfbte 10 dollars et contient une puce PIC18F, un micrologiciel pr\xe9programm\xe9, un \xe9metteur-r\xe9cepteur et un circuit suppl\xe9mentaire. Une solution rapide ou un message cryptographique peut vaincre l'injecteur CAN. Ian Haken d\xe9crit plusieurs fa\xe7ons dont les constructeurs automobiles pourraient contribuer \xe0 s\xe9curiser les voitures, mais l'exploitation criminelle de la technique est largement r\xe9pandue. Il s'agit d'un probl\xe8me \xe0 l'\xe9chelle de l'industrie qui n\xe9cessite une mise \xe0 jour du logiciel de l'ECU pour vaincre les voleurs."]}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35452963",children:"Discussion Service"}),".\nUne technique de vol de voiture sans cl\xe9 connue sous le nom de CAN Injection a \xe9t\xe9 mise en \xe9vidence sur Hacker News. Les consommateurs doivent se m\xe9fier du cryptage ou de la signature du bus CAN, car cela peut limiter les outils de diagnostic tiers, ce qui augmente les co\xfbts de r\xe9paration. Le bus CAN contr\xf4le de nombreuses fonctions du v\xe9hicule et les constructeurs automobiles optimisent les co\xfbts de mani\xe8re impitoyable. Les constructeurs automobiles sont l\xe9galement tenus de se s\xe9parer des concessionnaires, mais certains commentaires critiquent leur respect de l'esprit de la loi. Les marques de voitures haut de gamme utilisent diverses mesures de s\xe9curit\xe9 pour emp\xeacher le piratage des v\xe9hicules, notamment des dispositifs d'immobilisation dot\xe9s de protocoles cryptographiques appropri\xe9s pour authentifier les messages de d\xe9marrage et de d\xe9blocage et des trames CAN/FlexRay/Ethernet sign\xe9es pour emp\xeacher l'usurpation de messages. Les voitures bon march\xe9 sont cibl\xe9es car elles sont faciles \xe0 voler, tandis que les voitures co\xfbteuses sont la cible de vols violents. L'exploit d\xe9crit dans l'article pourrait \xeatre appliqu\xe9 \xe0 presque tous les v\xe9hicules non connect\xe9s fabriqu\xe9s au cours de la derni\xe8re d\xe9cennie. L'utilisation du bus CAN dans les syst\xe8mes critiques tels que l'aviation et l'automobile est due \xe0 sa simplicit\xe9 de c\xe2blage et \xe0 sa rentabilit\xe9."]}),"\n",(0,t.jsx)(s.h2,{id:"les-ing\xe9nieurs-de-firefox-d\xe9couvrent-un-bogue-de-windows-defender-qui-entra\xeene-une-utilisation-\xe9lev\xe9e-de-lunit\xe9-centrale",children:"Les ing\xe9nieurs de Firefox d\xe9couvrent un bogue de Windows Defender qui entra\xeene une utilisation \xe9lev\xe9e de l'unit\xe9 centrale."}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"https://bugzilla.mozilla.org/show_bug.cgi?id=1441918#c82",children:"Original"}),".\nN/A (Ce texte n'est pas li\xe9 au sujet)."]}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35458746",children:"Discussion Service"}),".\nLes ing\xe9nieurs de Firefox ont d\xe9couvert un bogue de Windows Defender causant l'utilisation du processeur sur le navigateur de Mozilla. Microsoft publie un correctif pour rem\xe9dier \xe0 ce probl\xe8me. D'autres produits AV peuvent \xe9galement \xeatre \xe0 l'origine de probl\xe8mes d'utilisation du processeur. Firefox fait plus d'appels syst\xe8me que Chrome pour des raisons de s\xe9curit\xe9. Une comparaison montre que Firefox est plus rapide que Chrome dans certains tests. Les experts discutent des limites de Defender, sugg\xe8rent le sandboxing et le MFA mat\xe9riel. Les utilisateurs d\xe9battent de l'efficacit\xe9 de Defender par rapport aux logiciels AV tiers. Certains utilisateurs signalent que Defender ralentit l'acc\xe8s au syst\xe8me de fichiers."]}),"\n",(0,t.jsx)(s.h2,{id:"segment-anything-model-sam-peut-d\xe9couper-nimporte-quel-objet-dans-une-image",children:'Segment Anything Model (SAM) peut "d\xe9couper" n\'importe quel objet dans une image'}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"https://segment-anything.com/",children:"Original"}),".\nLe mod\xe8le Segment Anything (SAM) d\xe9velopp\xe9 par Meta AI peut isoler n'importe quel objet dans une image avec une grande pr\xe9cision. Il peut identifier et segmenter avec succ\xe8s des objets, m\xeame lorsqu'ils sont partiellement visibles ou occult\xe9s. SAM am\xe9liore les mod\xe8les pr\xe9c\xe9demment d\xe9velopp\xe9s qui s'appuyaient sur des indices de localisation ou des objets saillants. Plut\xf4t que d'utiliser ces indices, SAM applique le m\xe9ta-apprentissage, en tirant parti de l'apprentissage d'un mod\xe8le existant, afin de pouvoir d\xe9tecter de petits ensembles de donn\xe9es biais\xe9s ou des objets non vus. SAM peut \xeatre utilis\xe9 pour des applications pratiques, comme l'\xe9dition d'images, ainsi que pour la recherche dans le domaine de la vision par ordinateur."]}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35455566",children:"Discussion Service"}),".\nSAM de Meta AI permet de g\xe9n\xe9rer des masques en temps r\xe9el pour \"d\xe9couper\" n'importe quel objet d'une image. La licence du mod\xe8le et ses impressionnantes capacit\xe9s d'inf\xe9rence pourraient le rendre populaire aupr\xe8s des experts en technologie. Les probl\xe8mes incluent une vitesse plus lente avec le mod\xe8le RTX 2080ti 11GB et une pr\xe9cision limit\xe9e avec les objets transparents. Certains consid\xe8rent que la strat\xe9gie de lancement de Meta AI s'inscrit dans le cadre de l'adoption de la RA. Les utilisateurs font l'\xe9loge de la r\xe9duction des co\xfbts d'annotation des donn\xe9es de SAM, mais critiquent sa vitesse et la comparent \xe0 celle d'iOS. Le d\xe9veloppement pourrait \xe9galement avoir une application potentielle pour les cam\xe9ras de s\xe9curit\xe9 et l'int\xe9gration d'AdobeAI."]}),"\n",(0,t.jsx)(s.h2,{id:"le-livre-blanc-de-bitcoin-est-cach\xe9-dans-chaque-copie-de-macos",children:"Le livre blanc de Bitcoin est cach\xe9 dans chaque copie de macOS"}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"https://waxy.org/2023/04/the-bitcoin-whitepaper-is-hidden-in-every-modern-copy-of-macos/",children:"Original"}),".\nUne copie PDF du livre blanc Bitcoin de Satoshi Nakamoto a \xe9t\xe9 d\xe9couverte dans toutes les copies modernes de macOS depuis Mojave en 2018, et il est possible d'y acc\xe9der par le biais d'un exemple de document dans l'utilitaire Image Capture. Le livre blanc est utilis\xe9 comme document d'exemple pour un p\xe9riph\xe9rique appel\xe9 \"Virtual Scanner II\", qui est soit cach\xe9, soit non install\xe9 pour tout le monde par d\xe9faut. La raison de son inclusion n'est pas encore claire, mais il pourrait s'agir d'un PDF multipage pratique et l\xe9ger \xe0 des fins de test. Il existe tr\xe8s peu d'informations en ligne sur Virtual Scanner II ou sur l'inclusion du livre blanc dans macOS."]}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35461011",children:"Discussion Service"}),".\nLe livre blanc Bitcoin est cach\xe9 dans chaque copie de macOS depuis 2019 ; la raison de son inclusion fait l'objet de sp\xe9culations, et les utilisateurs mettent en garde contre le minage sur les iPhones. La somme de hachage correspond \xe0 la version originale, mais les th\xe9ories varient sur la raison de son inclusion. Des plaintes ont \xe9t\xe9 d\xe9pos\xe9es au sujet de l'approbation d'un syst\xe8me de Ponzi, mais les utilisateurs pr\xe9cisent qu'il est cach\xe9. Apple l'a peut-\xeatre inclus pour des raisons de commodit\xe9, mais le message suscite un dialogue sur l'impact de Bitcoin. Les utilisateurs commentent l'image utilis\xe9e dans un article, la taille du fichier PDF et le fait que la technologie a perdu son plaisir artistique."]}),"\n",(0,t.jsx)(s.h2,{id:"lancien-directeur-technique-de-square-bob-lee-poignard\xe9-\xe0-mort-dans-le-centre-de-san-francisco",children:"L'ancien directeur technique de Square, Bob Lee, poignard\xe9 \xe0 mort dans le centre de San Francisco"}),"\n",(0,t.jsxs)(s.p,{children:["(",(0,t.jsx)(s.a,{href:"https://sfstandard.com/criminal-justice/san-francisco-stabbing-victim-bob-lee-former-cto-square-mobilecoin/",children:"https://sfstandard.com/criminal-justice/san-francisco-stabbing-victim-bob-lee-former-cto-square-mobilecoin/"}),").\nL'ancien directeur technique de Square, Bob Lee, a \xe9t\xe9 poignard\xe9 \xe0 mort dans le centre-ville de San Francisco, selon The Standard. M. Lee \xe9tait le chef de produit de MobileCoin, une soci\xe9t\xe9 de cryptographie de San Francisco, et un membre appr\xe9ci\xe9 des communaut\xe9s de d\xe9veloppement de logiciels et de technologie de la r\xe9gion de la baie. La police de San Francisco n'a pas communiqu\xe9 d'autres d\xe9tails ni l'identit\xe9 de la victime, et demande des t\xe9moins oculaires et des s\xe9quences vid\xe9o pour son enqu\xeate. Au 2 avril, San Francisco comptait 12 homicides, soit deux de plus qu'\xe0 la m\xeame p\xe9riode l'ann\xe9e derni\xe8re. Le Standard couvre des sujets importants, notamment les questions de justice p\xe9nale \xe0 San Francisco, et fournit des bulletins d'information ainsi qu'une vue d'ensemble de la politique et de la culture de San Francisco."]}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35452426",children:"Discussion Service"}),".\nL'ancien directeur technique de Square, Bob Lee, a \xe9t\xe9 poignard\xe9 \xe0 San Francisco ; les commentaires font r\xe9f\xe9rence \xe0 de nouveaux d\xe9tails."]}),"\n",(0,t.jsx)(s.h2,{id:"les-arguments-en-faveur-de-linterdiction-des-m\xe9dias-sociaux-aux-enfants",children:"Les arguments en faveur de l'interdiction des m\xe9dias sociaux aux enfants"}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"https://www.newyorker.com/news/our-columnists/the-case-for-banning-children-from-social-media",children:"Original"}),".\nLe d\xe9bat sur l'interdiction des m\xe9dias sociaux aux enfants est en cours en raison des pr\xe9occupations li\xe9es \xe0 la d\xe9pendance et \xe0 la n\xe9gativit\xe9. Certains projets de loi ont \xe9t\xe9 adopt\xe9s pour restreindre l'acc\xe8s des mineurs aux sites de m\xe9dias sociaux et supprimer les fonctions addictives, mais cela soul\xe8ve des questions de libert\xe9s civiles et limite l'acc\xe8s aux informations et \xe0 des perspectives diff\xe9rentes, ce qui pose la question de la mani\xe8re dont les m\xe9dias sociaux devraient \xeatre trait\xe9s. Alors que les tribunaux ont annul\xe9 les protections en ligne pour la s\xe9curit\xe9 des enfants, la cr\xe9ation de messages anti-d\xe9pendance et les restrictions l\xe9gales pr\xe9sentent des conflits potentiels avec les droits du premier amendement, et les parents pourraient \xeatre amen\xe9s \xe0 retirer physiquement les \xe9crans. La protection des enfants en ligne fait l'objet d'un d\xe9bat politique et culturel, ce qui laisse peu de confiance dans la capacit\xe9 du gouvernement \xe0 r\xe9glementer les entreprises de m\xe9dias sociaux."]}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35447588",children:"Discussion Service"}),".\nUn article pr\xe9conise l'interdiction des m\xe9dias sociaux aux moins de 18 ans en raison du risque de d\xe9pendance aux drogues ; la r\xe9glementation de ce type de contenu pose des difficult\xe9s. Un d\xe9bat sur la d\xe9finition et l'influence des publicit\xe9s destin\xe9es aux enfants soul\xe8ve des inqui\xe9tudes quant \xe0 la r\xe9glementation de la publicit\xe9. Les effets n\xe9fastes des m\xe9dias sociaux sur la sant\xe9 mentale et le d\xe9veloppement personnel sont \xe9voqu\xe9s, ce qui conduit \xe0 sugg\xe9rer d'interdire les m\xe9dias sociaux d'entreprise et les flux algorithmiques. Une interdiction g\xe9n\xe9rale des m\xe9dias sociaux n'est pas consid\xe9r\xe9e comme la solution ; des approches nuanc\xe9es sont n\xe9cessaires. Les utilisateurs de Discussion Service discutent des moyens efficaces de limiter le temps pass\xe9 devant un \xe9cran et d'en combattre les effets n\xe9gatifs. Le d\xe9bat porte sur la recherche d'un \xe9quilibre entre la libert\xe9 individuelle et la responsabilit\xe9 soci\xe9tale. Les inqui\xe9tudes concernant le contr\xf4le des m\xe9dias sociaux et la lib\xe9ration de dopamine dans le cerveau suscitent des discussions sur l'interdiction des m\xe9dias sociaux aliment\xe9s par des algorithmes. La faisabilit\xe9 et l'intrusion potentielle dans la vie priv\xe9e sont mises en avant comme des pr\xe9occupations concernant les contr\xf4les d'identit\xe9 obligatoires pour les comptes de m\xe9dias sociaux. Aucune nouvelle technologie ou publication majeure n'est abord\xe9e."]}),"\n",(0,t.jsx)(s.h2,{id:"dang-aura-bient\xf4t-65-535-points-de-karma",children:"Dang aura bient\xf4t 65 535 points de karma."}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"https://news.ycombinator.com/user?id=dang",children:"Original"}),".\nL'utilisateur Discussion Service 'dang' devrait bient\xf4t atteindre 65 535 points karma, ce qui est la limite maximale due \xe0 l'utilisation par le syst\xe8me d'un nombre entier sign\xe9 de 16 bits."]}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35460732",children:"Discussion Service"}),".\nDaniel Gackle, alias Dang, sur le point d'atteindre 65 535 points de karma. La section des commentaires est remplie d'\xe9loges sur le travail de Dang. Les utilisateurs se demandent si le karma va passer et discutent du passage \xe0 un int de 32 bits. Le style de mod\xe9ration et l'implication de Y Combinator sont remis en question. L'obtention d'un karma \xe9lev\xe9 est consid\xe9r\xe9e comme un moyen d'appr\xe9cier le travail de Dang. Atteindre un niveau de karma \xe9lev\xe9 permet d'obtenir des capacit\xe9s suppl\xe9mentaires sur Discussion Service, telles que le vote par le haut et le vote par le bas."]}),"\n",(0,t.jsx)(s.h2,{id:"r\xe9seaux-neuronaux--de-z\xe9ro-\xe0-h\xe9ros",children:"R\xe9seaux neuronaux : De z\xe9ro \xe0 h\xe9ros"}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"https://karpathy.ai/zero-to-hero.html",children:"Original"}),".\nLe cours \"Neural Networks : Zero to Hero\" par Andrej Karpathy enseigne la construction de r\xe9seaux neuronaux \xe0 partir de z\xe9ro dans le code. Le cours commence par les bases de la r\xe9tropropagation et progresse vers les r\xe9seaux neuronaux profonds modernes tels que GPT. Le cours se concentre sur les mod\xe8les de langage car ils constituent un excellent moyen d'apprendre l'apprentissage profond. Les pr\xe9requis incluent une programmation solide et un niveau introductif en math\xe9matiques. Le cours comprend la construction de micrograd, makemore, un MLP, et la plong\xe9e dans certains aspects internes des MLP. Devenir un Backprop Ninja et construire WaveNet sont \xe9galement abord\xe9s. Le cours se termine par la construction de GPT. Les vid\xe9os fournissent une explication \xe9tape par \xe9tape et se concentrent sur l'acquisition de comp\xe9tences et d'intuition sur la fa\xe7on dont les r\xe9seaux neuronaux sont optimis\xe9s. Le cours recommande aux spectateurs de regarder les vid\xe9os makemore pr\xe9c\xe9dentes pour \xeatre \xe0 l'aise avec le cadre de mod\xe9lisation autor\xe9gressive du langage et les bases des tenseurs et de PyTorch nn."]}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35459031",children:"Discussion Service"}),".\nLe cours d'Andrej Karpathy \" Neural Networks : Zero to Hero\" d'Andrej Karpathy gagne plus de 300 points sur Hacker News en 6 heures. Les utilisateurs de Discussion Service font l'\xe9loge de son style d'enseignement et recommandent de coder apr\xe8s avoir regard\xe9 les vid\xe9os. Son cours sur les r\xe9seaux neuronaux dirig\xe9 par des pairs re\xe7oit des commentaires positifs bien qu'il n'en fasse pas mention. La syntaxe sp\xe9cifique \xe0 Python dans les vid\xe9os pourrait poser probl\xe8me \xe0 certains utilisateurs. Une discussion \xe9value l'accent mis par le cours sur la r\xe9gression logistique et le perceptron. Les participants ont trouv\xe9 le cours facile \xe0 comprendre et recommandent d'autres cours pour les d\xe9butants. Certains utilisateurs s'interrogent sur les connaissances minimales des d\xe9veloppeurs web, et un utilisateur a une th\xe9orie sur le lien entre la ML et l'alg\xe8bre de Hopf."]}),"\n",(0,t.jsx)(s.h2,{id:"une-astuce-pour-atteindre-le-flux--laissez-votre-travail-bris\xe9",children:"Une astuce pour atteindre le flux : Laissez votre travail bris\xe9"}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"https://census.dev/blog/an-on-ramp-to-flow",children:"Original"}),".\nL'article traite de la difficult\xe9 d'atteindre un \xe9tat de \"fluidit\xe9\" dans les t\xe2ches d'ing\xe9nierie et propose une astuce pour retrouver la fluidit\xe9. L'auteur sugg\xe8re de laisser son travail dans un \xe9tat manifestement d\xe9fectueux mais facile \xe0 r\xe9parer avant de s'\xe9loigner. Cela permet d'avoir un point de d\xe9part clair lorsqu'on reprend le travail, ce qui cr\xe9e un \xe9lan et une confiance. L'article reconna\xeet que cette approche n'est peut-\xeatre pas universelle ou applicable en \xe9quipe, mais il invite les lecteurs \xe0 lui faire part de leurs commentaires sur d'autres astuces. L'article mentionne \xe9galement bri\xe8vement l'ing\xe9nierie du recensement et les possibilit\xe9s d'emploi."]}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35456059",children:"Discussion Service"}),".\nLes utilisateurs de Discussion Service partagent des conseils pour atteindre l'\xe9tat de fluidit\xe9 en laissant le travail inachev\xe9, y compris la m\xe9thode \"park facing downhill\". Un directeur de l'ing\xe9nierie a mis en place la m\xe9thode consistant \xe0 quitter le travail \xe0 18 heures pour \xe9viter l'\xe9puisement professionnel, mais y a mis fin en raison du pr\xe9sent\xe9isme. Les utilisateurs discutent des avantages et des risques li\xe9s \xe0 l'application de r\xe8gles strictes en mati\xe8re de d\xe9lais et au changement de culture professionnelle. Certains partagent des conseils de productivit\xe9 tels que l'\xe9criture des prochaines \xe9tapes et la pratique du TDD. Laisser le code dans un \xe9tat \"cass\xe9\" peut aider \xe0 le reprendre plus tard, mais les r\xe9sultats sont mitig\xe9s."]}),"\n",(0,t.jsx)(s.h2,{id:"la-ram-est-elle-effac\xe9e-avant-d\xeatre-utilis\xe9e-dans-un-autre-conteneur-lxc-",children:"La RAM est-elle effac\xe9e avant d'\xeatre utilis\xe9e dans un autre conteneur LXC ?"}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"https://security.stackexchange.com/questions/269507/is-ram-wiped-before-use-in-another-lxc-container",children:"Original"}),".\nUn message sur Information Security Stack Exchange demande si la m\xe9moire vive est effac\xe9e avant d'\xeatre utilis\xe9e dans un autre conteneur LXC, ce qui conduit \xe0 une discussion sur le surprovisionnement de la m\xe9moire vive dans LXC, un utilisateur indiquant que la m\xe9moire allou\xe9e \xe0 un processus pr\xe9c\xe9dent dans un conteneur est effac\xe9e. Un post sur Hacker News va plus loin, discutant des biblioth\xe8ques partag\xe9es et des protections de l'espace de noms de l'utilisateur, et une r\xe9ponse clarifie que les pages sont effac\xe9es avant l'allocation, que le surprovisionnement n'entra\xeene pas de partage, et que la m\xe9moire LXC est allou\xe9e aux processus via les espaces de noms, mais que les processus sont s\xe9par\xe9s des ressources de l'h\xf4te. Enfin, il est not\xe9 que la gestion de la m\xe9moire bas\xe9e sur la glibc n'implique pas de nettoyage et que les pages libres peuvent contenir des donn\xe9es."]}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35451863",children:"Discussion Service"}),".\nLes utilisateurs de Hacker News ont discut\xe9 de l'efficacit\xe9 et de la n\xe9cessit\xe9 de la mise \xe0 z\xe9ro automatique de la m\xe9moire sous Linux, certains sugg\xe9rant des m\xe9thodes alternatives pour nettoyer la m\xe9moire inutilis\xe9e. Un utilisateur a soulign\xe9 que le probl\xe8me r\xe9side dans la conception de l'appel syst\xe8me fork() d'UNIX, et que de nombreux logiciels gourmands en m\xe9moire sont encore confront\xe9s \xe0 des probl\xe8mes d'OOM. D'autres commentaires traitent des diff\xe9rences entre l'allocation de m\xe9moire overcommit et non-overcommit sous Linux et de l'importance de fixer des limites. L'article fournit des perspectives nuanc\xe9es sur l'allocation de m\xe9moire sous Linux et s'adresse aux experts dans ce domaine."]}),"\n",(0,t.jsx)(s.h2,{id:"perspective--bi-open-source-aliment\xe9e-par-webassembly",children:"Perspective : BI Open Source aliment\xe9e par WebAssembly"}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"https://perspective.finos.org/",children:"Original"}),".\nPerspective est un composant interactif d'analyse et de visualisation de donn\xe9es, con\xe7u pour le streaming et les grands ensembles de donn\xe9es avec des rapports configurables, des tableaux de bord et des carnets de notes. Il est dot\xe9 d'un moteur de requ\xeate en continu \xe0 m\xe9moire r\xe9duite en C++ et Python et d'une interface utilisateur pr\xe9sent\xe9e sous la forme d'un \xe9l\xe9ment personnalis\xe9 aliment\xe9 par WebAssembly ou WebSocket. L'interface utilisateur comprend des tableaux de bord interactifs qui peuvent \xeatre int\xe9gr\xe9s dans n'importe quel cadre d'application web. Perspective.js s'appuie sur WebAssembly et Apache Arrow pour des performances comparables \xe0 celles d'un ordinateur de bureau dans le navigateur. PerspectivePython met en \u0153uvre l'API Perspective directement en Python pour la recherche ou la production. Il existe des widgets virtualis\xe9s et \xe9volutifs, et le projet est disponible sur GitHub avec des guides d'utilisation et de programmation."]}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35455850",children:"Discussion Service"}),".\nL'outil BI open-source Perspective, aliment\xe9 par WebAssembly, est lou\xe9 pour ses puissantes fonctionnalit\xe9s, malgr\xe9 des probl\xe8mes de performance : les solutions sugg\xe9r\xe9es incluent l'utilisation d'une option plus l\xe9g\xe8re. Les cr\xe9ateurs de Perspective travaillent \xe0 l'am\xe9lioration des performances et de la compatibilit\xe9 mobile. Quelques inqui\xe9tudes ont \xe9t\xe9 soulev\xe9es concernant la prise en charge de Firefox et l'accessibilit\xe9/la conception adapt\xe9e au clavier. Les limites de Sciter ont \xe9t\xe9 discut\xe9es, les biblioth\xe8ques Tauri sont consid\xe9r\xe9es comme potentiellement utiles. Des am\xe9liorations de performance sont n\xe9cessaires pour le projet Perspective."]}),"\n",(0,t.jsx)(s.h2,{id:"grid-world",children:"Grid World"}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"https://alex.miller.garden/grid-world/",children:"Original"}),".\nL'article \"Grid World\" d'Alexander Miller explore le r\xf4le des grilles dans sa vie, de l'enfance \xe0 l'\xe2ge adulte, y compris leur impact sur la technologie, l'art et la navigation. L'article aborde le pouvoir des grilles dans la cartographie et le contr\xf4le de l'espace, comme on le voit dans des jeux tels que Battleship et Chess. La grille devient un pivot central qui relie les exp\xe9riences personnelles de Miller, montrant comment elle fait partie de nos vies. Miller a cr\xe9\xe9 la grille pour The HTML Review en 2023."]}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35455770",children:"Discussion Service"}),".\nLes utilisateurs de Discussion Service sont fascin\xe9s par l'exceptionnelle ma\xeetrise et le savoir-faire de Grid World en mati\xe8re de conception et de d\xe9veloppement de sites web, ainsi que par son impact sur la perception. L'article explore la sous-structure de la grille par rapport \xe0 nos souvenirs et au monde, et s'accompagne de visuels en pixel art. Les commentaires soulignent le lien entre les neurosciences et les cellules de la grille, tout en soulevant des critiques sur la rationalisation et la couverture de la grille sur la nature. Un utilisateur trouve qu'il est difficile de perfectionner les aspects visuels de son projet personnel. Les utilisateurs discutent des grilles du Queens et de l'histoire qui les sous-tend. Un utilisateur de Discussion Service fait part de ses observations sur la conformit\xe9 de la grille des rues de New York. Une d\xe9coration en forme de table g\xe9n\xe8re des salles de r\xe9union faiblement \xe9clair\xe9es tout en \xe9voluant dans le temps, construite avec du simple javascript sans aucune biblioth\xe8que pour un exercice technique amusant."]}),"\n",(0,t.jsx)(s.h2,{id:"openai-tokenizer",children:"OpenAI Tokenizer"}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"https://platform.openai.com/tokenizer",children:"Original"}),".\nL'API OpenAI est une technologie qui n\xe9cessite l'activation de JavaScript."]}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35453400",children:"Discussion Service"}),".\nOpenAI a publi\xe9 un nouveau tokenizer pour mieux comprendre les mod\xe8les GPT. Le tokenizer divise le texte en unit\xe9s de sous-mots pour un traitement efficace, mais ils n'ont pas de signification inh\xe9rente. Les utilisateurs de Discussion Service discutent des limites de l'outil, telles que le regroupement bas\xe9 sur les espaces et les traitements de capitalisation. Les codages cr\xe9\xe9s \xe0 l'aide du codage par paires d'octets ne sont souvent pas adapt\xe9s aux langues sous-repr\xe9sent\xe9es. OpenAI facture par jeton en raison du fonctionnement du mod\xe8le bas\xe9 sur les jetons."]}),"\n",(0,t.jsx)(s.h2,{id:"tabloid---le-langage-de-programmation-des-titres-racoleurs",children:"Tabloid - Le langage de programmation des titres racoleurs"}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"https://tabloid-thesephist.vercel.app/",children:"Original"}),".\nTabloid est un nouveau langage de programmation cr\xe9\xe9 pour g\xe9n\xe9rer des titres ridicules et qui font mouche, comme ceux que l'on trouve dans les tablo\xefds. Le langage utilise une combinaison de traitement du langage naturel, d'apprentissage automatique et d'approvisionnement par la foule pour cr\xe9er des titres avec des mod\xe8les linguistiques de type \"clickbaity\". Il s'agit d'un langage amusant et divertissant qui ne sert \xe0 rien, mais qui illustre parfaitement la mani\xe8re dont la programmation peut \xeatre \xe0 la fois utile et amusante. Le cr\xe9ateur de Tabloid pr\xe9voit de l'utiliser pour cr\xe9er une plateforme permettant \xe0 tout un chacun de cr\xe9er ses propres titres racoleurs. Les utilisateurs de Discussion Service trouvent cet outil int\xe9ressant et utile pour comprendre le traitement du langage naturel."]}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35447580",children:"Discussion Service"}),".\nUn projet r\xe9cent sur Hacker News intitul\xe9 Tabloid - The Clickbait Headline Programming Language (Tablo\xefde - Le langage de programmation des titres racoleurs). Le projet est fascinant, \xe9crit par un auteur qui pr\xe9tend avoir \xe9crit d'autres langages qui sont sans doute plus utiles. Un utilisateur de Discussion Service a publi\xe9 un programme en Tabloid qui prend cinq nombres et renvoie le produit des trois premiers nombres plus le produit des deux derniers. L'auteur est quelqu'un qui a livr\xe9 de nombreux projets int\xe9ressants, et qui a m\xeame utilis\xe9 Oak pour construire une infrastructure logicielle personnelle, entre autres choses. Un autre utilisateur de Discussion Service a fait remarquer que le fait de tout \xe9crire \xe0 partir de z\xe9ro est plus viable pour les d\xe9veloppeurs solitaires, mais pas pour les \xe9quipes, o\xf9 il est pr\xe9f\xe9rable d'opter pour la m\xe9thode \"ennuyeuse\"."]}),"\n",(0,t.jsx)(s.h2,{id:"gpt4-simulant-un-serveur-ftp-\xe0-ftpdisneycom",children:"GPT4 simulant un serveur FTP \xe0 ftp.disney.com"}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"https://www.filestash.app/2023/04/01/chat-gpt-acting-as-a-ftp-server/",children:"Original"}),".\nChat GPT-4 est capable de simuler un serveur FTP pour Disney, en utilisant l'outil ftp cli de base et les invites \xe0 venir pour ex\xe9cuter les commandes comme le ferait un vrai utilisateur. Le serveur simul\xe9 comprend du contenu exclusif de Disney dans des dossiers tels que des films, des bandes sonores et des fonds d'\xe9cran, et GPT-4 s'av\xe8re capable de naviguer dans des syst\xe8mes de fichiers locaux et distants. La nouvelle technologie fonctionne bien, d\xe9passant les attentes et d\xe9montrant sa capacit\xe9 \xe0 cr\xe9er des contenus attrayants pour les passionn\xe9s de Disney. L'article laisse entrevoir de futures utilisations de GPT-4 dans des plugins d'interpr\xe9tation de code permettant d'acc\xe9der \xe0 de faux serveurs \xe0 partir de clients FTP."]}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35450315",children:"Discussion Service"}),".\nUn article sur Hacker News traite de la simulation par GPT4 d'un serveur FTP \xe0 ftp.disney.com. Les utilisateurs se demandent si cela peut \xeatre consid\xe9r\xe9 comme une \"hallucination\", bien que l'IA puisse simuler ou \"halluciner\". La pr\xe9cision des r\xe9ponses g\xe9n\xe9r\xe9es par l'IA et la perception de ces r\xe9sultats comme des \"hallucinations\" sont \xe9galement des points de discussion. Parmi les autres sujets abord\xe9s, citons : la possibilit\xe9 que les films ou les \xe9missions de t\xe9l\xe9vision g\xe9n\xe9r\xe9s par l'IA soient sans valeur, le r\xf4le de l'espace latent et du langage dans les MLD, l'impact de la technologie sur la soci\xe9t\xe9 et les limites des capacit\xe9s actuelles de l'IA. Certains utilisateurs mettent en garde contre une surinterpr\xe9tation des capacit\xe9s de l'IA et notent que ses limites sont souvent n\xe9glig\xe9es."]}),"\n",(0,t.jsx)(s.h2,{id:"utilisation-de-mmap-pour-acc\xe9l\xe9rer-le-chargement-de-llama",children:"Utilisation de mmap pour acc\xe9l\xe9rer le chargement de LLaMA"}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"https://justine.lol/mmap/",children:"Original"}),".\nLLaMA utilise mmap() pour charger les mod\xe8les 100 fois plus vite, augmente la stabilit\xe9 de la RAM et permet \xe0 plusieurs processus de s'ex\xe9cuter simultan\xe9ment. Les utilisateurs de Linux b\xe9n\xe9ficient d'une am\xe9lioration de 100x, tandis que Windows et MacOS b\xe9n\xe9ficient d'une am\xe9lioration de 10x. Le nouveau chargeur mmap() est maintenant disponible sur GitHub sous licence MIT. Le collaborateur anonyme @Slaren a ajout\xe9 le support mmap() \xe0 LLaMA-7B, permettant des temps de chargement instantan\xe9s sans changement de format de fichier. Le nouveau format de fichier aligne les tenseurs sur une fronti\xe8re de 32 octets. L'article explore les am\xe9liorations potentielles en mati\xe8re d'utilisation du disque et de perturbation des performances. Justine Tunney \xe9crit sur Twitter et Github dans des utilitaires standard, destin\xe9s aux experts du domaine. L'article est clair et concis, sans parti pris ni d\xe9clarations politiques ou religieuses. Un utilisateur de Discussion Service commente que le billet de Tunney est une excellente ressource pour l'apprentissage."]}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35455930",children:"Discussion Service"}),".\nL'utilisation de mmap pour acc\xe9l\xe9rer le chargement de LLaMA est l'objectif principal de l'article, malgr\xe9 les probl\xe8mes d'attribution et les questions techniques dans la section des commentaires. Les avantages et les inconv\xe9nients de mmap sont discut\xe9s, ainsi que les m\xe9rites techniques de LLaMA.cpp de Facebook. Les utilisateurs discutent de l'utilit\xe9 des changements apport\xe9s \xe0 LLaMA et des avantages et inconv\xe9nients de diverses fonctionnalit\xe9s, fournissant ainsi des informations pr\xe9cieuses aux lecteurs avertis d\xe9sireux d'en savoir plus sur l'IA et l'impl\xe9mentation de mod\xe8les. L'article met en \xe9vidence une approche d'ing\xe9nierie des syst\xe8mes face \xe0 un probl\xe8me et une tendance impliquant du code propri\xe9taire dans les biblioth\xe8ques, g\xe9n\xe9rant une discussion sur l'utilisation de Huge Pages et la difficult\xe9 de r\xe9soudre les goulets d'\xe9tranglement IO. L'am\xe9lioration r\xe9volutionnaire des performances gr\xe2ce \xe0 mmap a attir\xe9 l'attention des experts dans ce domaine."]})]})}function c(e={}){const{wrapper:s}={...(0,r.R)(),...e.components};return s?(0,t.jsx)(s,{...e,children:(0,t.jsx)(d,{...e})}):d(e)}}}]);